import json,hashlib,datetime,subprocess
from pathlib import Path
p=Path(__file__).resolve().parent;folder=p/'go-source-graph-determinism-v1';folder.mkdir();request=json.loads((p/'go-source-graph-controls-v1/interface-not-runtime-concrete.request.json').read_text())
for pkg in request['packages']:
 for f in pkg['files']:f['source']=f['source'].replace('\n',';');f['sha256']=hashlib.sha256(f['source'].encode()).hexdigest()
raw=json.dumps(request).encode();(folder/'request.json').open('xb').write(raw);binary=p/'offline-go-type-observer-v4/observer';(folder/'protocol.json').open('x').write(json.dumps({'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'hypothesis':'Sorting declarations only by file/line and relations only by file/line/column may leave map iteration ties nondeterministic for valid one-line Go; exact-recovery output requires deterministic tie handling.','runs':8,'binary_sha256':hashlib.sha256(binary.read_bytes()).hexdigest(),'request_sha256':hashlib.sha256(raw).hexdigest(),'expected':'Eight semantically identical observation packets should have equal list order and canonical packet hash.','role':'Owned serialization recovery mechanism; no new source family/model evaluation'},indent=2)+'\n');variants={};normalized={};rows=[]
def digest(o):return hashlib.sha256(json.dumps(o,sort_keys=True,separators=(',',':')).encode()).hexdigest()
for i in range(8):
 r=subprocess.run([str(binary)],input=raw,capture_output=True,timeout=25);(folder/f'run-{i+1:02d}.stdout.json').open('xb').write(r.stdout);packet=json.loads(r.stdout);assert packet['status']=='TYPECHECKED_FROZEN_SOURCE_GRAPH';h=digest(packet);variants[h]=variants.get(h,0)+1;packet['declarations']=sorted(packet['declarations'],key=lambda r:json.dumps(r,sort_keys=True));packet['relations']=sorted(packet['relations'],key=lambda r:json.dumps(r,sort_keys=True));n=digest(packet);normalized[n]=normalized.get(n,0)+1;rows.append({'run':i+1,'packet_sha256':h,'order_normalized_sha256':n})
out={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'records':rows,'packet_variants':variants,'order_normalized_variants':normalized,'exact_replay_deterministic_observed':len(variants)==1,'semantic_relation_change_observed':len(normalized)!=1,'target_source_executed':False,'model_calls':0};(folder/'results.json').open('x').write(json.dumps(out,indent=2)+'\n');print(json.dumps({'runs':8,'packet_variants':len(variants),'order_normalized_variants':len(normalized),'deterministic':len(variants)==1}))
